/bin/bash -lc "node --input-type=module <<'NODE'
import { chromium } from '@playwright/test'
const browser = await chromium.launch({ headless: true })
const page = await browser.newPage()
let request
page.on('request', (req) => {
  if (req.url().includes('category=featured') && req.headers()['next-router-prefetch'] === '2') request = req
})
await page.goto('http://127.0.0.1:3000/')
await page.waitForTimeout(1000)
console.log('HEADERS', JSON.stringify(request?.headers()))
if (request) {
  const started = Date.now()
  const response = await fetch(request.url(), { headers: request.headers() })
  const body = await response.text()
  console.log('BODY', JSON.stringify({ status: response.status, elapsed: Date.now()-started, length: body.length, featured: body.includes('Desk Lamp'), fallback: body.includes('Loading category'), excerpt: body.slice(0, 1600) }))
}
await browser.close()
NODE"

