/bin/bash -lc "node --input-type=module <<'NODE'
import { chromium } from '@playwright/test'
const browser = await chromium.launch({ headless: true })
for (const [label, slug, products] of [
  ['Featured products', 'featured', ['Desk Lamp', 'Wool Blanket']],
  ['Products on sale', 'sale', ['Canvas Tote', 'Travel Mug']],
]) {
  const page = await browser.newPage()
  const responses = []
  page.on('requestfinished', request => {
    if ("'!request.url().includes(`/catalog?category=${slug}`)) return
    responses.push((async () => {
      const response = await request.response()
      try {
        const body = await response.text()
        return { kind: request.headers()['"'next-router-prefetch'], segment: request.headers()['next-router-segment-prefetch'], containsProducts: products.every(product => body.includes(product)), containsFallback: body.includes('Loading category') }
      } catch { return { kind: request.headers()['next-router-prefetch'], unavailable: true } }
    })())
  })
  await page.goto('http://127.0.0.1:3000/')
  await page.waitForTimeout(2500)
  await page.evaluate(() => {
    window.loadingSeen = false
    new MutationObserver(() => {
      if (document.body.textContent.includes('Loading category...')) window.loadingSeen = true
    }).observe(document.body, { subtree: true, childList: true, characterData: true })
  })
  const started = Date.now()
  await page.getByRole('link', { name: label }).click()
  await page.getByRole('heading', { name: label, level: 2 }).waitFor()
  console.log(JSON.stringify({ slug, elapsed: Date.now()-started, url: page.url(), loadingSeen: await page.evaluate(() => window.loadingSeen), products: await page.locator('section li').allTextContents(), responses: await Promise.all(responses) }))
  await page.close()
}
await browser.close()
NODE"

