/bin/bash -lc "node --input-type=module <<'NODE'
import { chromium } from '@playwright/test'
const browser = await chromium.launch({ headless: true })
for (const label of ['Featured products', 'Products on sale']) {
  const page = await browser.newPage()
  const events = []
  const pending = []
  const started = Date.now()
  for (const event of ['request', 'requestfinished', 'requestfailed']) {
    page.on(event, req => {
      if ("'!req.url().includes('"'/catalog')) return
      const entry = { t: Date.now()-started, event, url: req.url(), kind: req.headers()['next-router-prefetch'] ?? 'navigation', segment: req.headers()['next-router-segment-prefetch'] }
      events.push(entry)
      if (event === 'requestfinished' && entry.kind === '2') {
        pending.push((async () => {
          try {
            const body = await (await req.response()).text()
            entry.featured = body.includes('Desk Lamp')
            entry.sale = body.includes('Canvas Tote')
          } catch { entry.bodyUnavailable = true }
        })())
      }
    })
  }
  await page.goto('http://127.0.0.1:3000/')
  await page.waitForTimeout(2200)
  await Promise.allSettled(pending)
  const clickAt = Date.now()-started
  await page.getByRole('link', { name: label }).click()
  await page.getByRole('heading', { name: label, level: 2 }).waitFor()
  await page.waitForTimeout(100)
  console.log(JSON.stringify({ label, clickAt, events }))
  await page.close()
}
await browser.close()
NODE"

